<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('POST');apiCsrf();$uid=apiAuth();$in=apiInput();$pid=apiId($in['product_id']??0);$qty=(int)($in['quantity']??1);if($qty<1)apiError('Invalid quantity',422);$db=apiDb();try{$db->beginTransaction();$s=$db->prepare('SELECT id FROM carts WHERE user_id=? AND status="active" LIMIT 1');$s->execute([$uid]);$cid=(int)$s->fetchColumn();if(!$cid){$s=$db->prepare('INSERT INTO carts(user_id,status) VALUES(?,"active")');$s->execute([$uid]);$cid=(int)$db->lastInsertId();}$s=$db->prepare('SELECT id FROM cart_items WHERE cart_id=? AND product_id=? AND variant_id IS NULL LIMIT 1');$s->execute([$cid,$pid]);$itemId=$s->fetchColumn();if($itemId){$s=$db->prepare('UPDATE cart_items SET quantity=quantity+?,updated_at=NOW() WHERE id=?');$s->execute([$qty,$itemId]);}else{$s=$db->prepare('SELECT retail_price FROM products WHERE id=? AND status="active" LIMIT 1');$s->execute([$pid]);$price=$s->fetchColumn();if($price===false)apiError('Product not found',404);$s=$db->prepare('INSERT INTO cart_items(cart_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');$s->execute([$cid,$pid,$qty,$price]);}$db->commit();apiResponse(['cart_id'=>$cid]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();apiException($e);}